# 05.2_methylartist_plots.R
# create figures directly from Methylartist segmeth TSV

# segmeth files contain 100-kb genomic windows generated by
# 05.1_methylartist_segmeth.sh
# each row represents one genomic window

# 1. read segmeth TSV
# 2. find sample-specific Methylartist columns
# 3. calculate informative methylation calls and 5mC percentage
# 4. apply the same minimum-call concept used by methylartist segplot
# 5. create ggplot2 strip, violin, and chromosome-landscape plots
# 6. save PDF & PNG files

# pct_5mC is a window-level methylation percentage
# a point in strip plot = one 100-kb window
# plots describe methylation within the coordinate system of a single assembly


# install package
library(ggplot2)

# == SETTINGS ==
# path, labels, colors, title, plotting options
# check INPUT SEGMETH TSV, OUTPUT DIRECTORY, PLOT_TITLE, KEEP_GROUPS, GROUP_COLORS

# INPUT SEGMETH TSV
#SEGMETH_FILE <- "/scratch/maelstr1/thesis/02_processed/cozumelus_LNG1401/methylartist/cozumelus_LNG1401.segmeth.tsv"
#SEGMETH_FILE <- "/scratch/maelstr1/thesis/02_processed/angusticeps_ANMO5228/methylartist/angusticeps_ANMO5228.segmeth.tsv"
#SEGMETH_FILE <- "/scratch/maelstr1/thesis/02_processed/deppii_ANMO5280/methylartist/deppii_ANMO5280.segmeth.tsv"
SEGMETH_FILE <- "/scratch/maelstr1/thesis/02_processed/deppii_LNG1403/methylartist/deppii_LNG1403.segmeth.tsv"

# OUTPUT DIRECTORY
#OUTPUT_DIR <- "/scratch/maelstr1/thesis/02_processed/cozumelus_LNG1401/methylartist/r_plots"
#OUTPUT_DIR <- "/scratch/maelstr1/thesis/02_processed/angusticeps_ANMO5228/methylartist/r_plots"
#OUTPUT_DIR <- "/scratch/maelstr1/thesis/02_processed/deppii_ANMO5280/methylartist/r_plots"
OUTPUT_DIR <- "/scratch/maelstr1/thesis/02_processed/deppii_LNG1403/methylartist/r_plots"

# minimum number of informative calls per 100-kb window
# match MINCALLS in 05.2_methylartist_plots.sh
# informative calls = methylated calls + unmethylated calls
MIN_CALLS <- 100

# FIGURE TITLE
PLOT_TITLE <- substitute(paste(italic("A. deppii"), " LNG1403"))
PLOT_SUBTITLE <- "5mC across 100-kb genomic windows"

# CATEGORIES
# cozumelus: use the two annotated subgenomes and omit unplaced contigs
#KEEP_GROUPS <- c("ang_subgenome", "dep_subgenome")
# sexual species:
KEEP_GROUPS <- c("genome")

# DISPLAY LABELS
# names on the left must match values in the seg_name column
# text on the right is what will appear in figures
GROUP_LABELS <- c(
  "ang_subgenome" = "A. angusticeps-derived",
  "dep_subgenome" = "A. deppii-derived",
  "genome"        = "Genome",
  "unplaced"      = "Unplaced"
)

# COLORS
# names must match the DISPLAY LABELS (not raw seg_name values)
# angusticeps (maternal) color #CC79A7
# deppii (paternal) color #56B4E9
# tertiary #009E73
# unplaced #999999
# Okabe-Ito color palette
GROUP_COLORS <- c(
  "A. angusticeps-derived" = "#CC79A7",
  "A. deppii-derived"      = "#56B4E9",
  "Genome"                 = "#56B4E9",
  "Unplaced"               = "#999999"
)

# PLOT
POINT_ALPHA <- 0.25
POINT_SIZE  <- 0.8
VIOLIN_ALPHA <- 0.60

# use a common biologically interpretable methylation scale for all plots.
Y_MIN <- 0
Y_MAX <- 100


# == READ SEGMETH TABLE ==
if (!file.exists(SEGMETH_FILE)) {
  stop("Input segmeth file does not exist: ", SEGMETH_FILE)
}

seg <- read.delim(
  SEGMETH_FILE,
  header = TRUE,
  stringsAsFactors = FALSE,
  check.names = FALSE
)

cat("\nLoaded segmeth file:\n  ", SEGMETH_FILE, "\n", sep = "")
cat("Rows/windows loaded:", nrow(seg), "\n")
cat("Columns loaded:", ncol(seg), "\n\n")

# first six columns should describe genomic segment/window
required_segment_columns <- c(
  "seg_id", "seg_chrom", "seg_start", "seg_end", "seg_name", "seg_strand"
)

missing_segment_columns <- setdiff(required_segment_columns, names(seg))
if (length(missing_segment_columns) > 0) {
  stop(
      "Missing expected segment columns: ",
      paste(missing_segment_columns, collapse = ", ")
  )
}


# == FIND SAMPLE-SPECIFIC METHYLARTIST COLUMNS ==
# Methylartist includes the BAM/sample name in its output column names
# find columns by suffix with grep()

find_one_column <- function(pattern, column_names, description) {
  hit <- grep(pattern, column_names, value = TRUE)

  if (length(hit) == 0) {
      stop("Could not find ", description, " column using pattern: ", pattern)
  }

  if (length(hit) > 1) {
      stop(
          "Found more than one possible ", description, " column:\n  ",
          paste(hit, collapse = "\n  ")
      )
  }

  hit
}

meth_col <- find_one_column(
  "_m_meth_calls$", names(seg), "methylated-call"
)

unmeth_col <- find_one_column(
  "_m_unmeth_calls$", names(seg), "unmethylated-call"
)

no_call_col <- find_one_column(
  "_m_no_calls$", names(seg), "no-call"
)

methfrac_col <- find_one_column(
  "_m_methfrac$", names(seg), "methylation-fraction"
)

readcount_col <- find_one_column(
  "_m_readcount$", names(seg), "read-count"
)

motifcount_col <- find_one_column(
  "_m_motifcount$", names(seg), "motif-count"
)

cat("Detected Methylartist columns:\n")
cat("  methylated calls:  ", meth_col, "\n", sep = "")
cat("  unmethylated calls:", unmeth_col, "\n", sep = "")
cat("  no calls:          ", no_call_col, "\n", sep = "")
cat("  methylation frac:  ", methfrac_col, "\n", sep = "")
cat("  read count:        ", readcount_col, "\n", sep = "")
cat("  motif count:       ", motifcount_col, "\n\n", sep = "")


# == CREATE READABLE ANALYSIS COLUMNS ==
seg$meth_calls <- as.numeric(seg[[meth_col]])
seg$unmeth_calls <- as.numeric(seg[[unmeth_col]])
seg$no_calls <- as.numeric(seg[[no_call_col]])
seg$methfrac <- as.numeric(seg[[methfrac_col]])
seg$readcount <- as.numeric(seg[[readcount_col]])
seg$motifcount <- as.numeric(seg[[motifcount_col]])

# informative calls are calls classified as methylated or unmethylated
# no-calls are excluded
seg$total_calls <- seg$meth_calls + seg$unmeth_calls

# Methylartist reports methfrac on a 0-1 scale (convert to percent for figures)
seg$pct_5mC <- seg$methfrac * 100

# midpoint of each genomic window (chromosome landscape plots)
seg$midpoint <- (seg$seg_start + seg$seg_end) / 2
seg$midpoint_Mb <- seg$midpoint / 1e6


# == FILTER WINDOWS FOR PLOTTING ==
# apply the same conceptual threshold as methylartist segplot -n 100
# windows with too few informative methylation calls are excluded
seg_plot <- seg[
  !is.na(seg$pct_5mC) &
  seg$total_calls >= MIN_CALLS &
  seg$seg_name %in% KEEP_GROUPS,
]

cat("Windows retained after filtering:", nrow(seg_plot), "of", nrow(seg), "\n")
cat("Minimum informative calls per retained window:", MIN_CALLS, "\n\n")

if (nrow(seg_plot) == 0) {
  stop("No windows remain after filtering. Check MIN_CALLS and KEEP_GROUPS.")
}

# translate raw Methylartist labels into figure-friendly labels
seg_plot$display_group <- unname(GROUP_LABELS[seg_plot$seg_name])

if (any(is.na(seg_plot$display_group))) {
  bad_groups <- unique(seg_plot$seg_name[is.na(seg_plot$display_group)])
  stop(
      "No display label defined for seg_name value(s): ",
      paste(bad_groups, collapse = ", ")
  )
}

# preserve the order specified in KEEP_GROUPS instead of alphabetizing labels
display_levels <- unname(GROUP_LABELS[KEEP_GROUPS])
seg_plot$display_group <- factor(
  seg_plot$display_group,
  levels = display_levels
)

# set chromosome order
# extract number from chromosome names
seg_plot$chrom_number <- as.numeric(
  sub(
    ".*_Chr_",
    "",
    seg_plot$seg_chrom
  )
)

# identify ancestry/subgenome
seg_plot$chrom_lineage <- ifelse(
  grepl("^angusticeps_", seg_plot$seg_chrom),
  "angusticeps",
  ifelse(
    grepl("^deppii_", seg_plot$seg_chrom),
    "deppii",
    NA_character_
  )
)

# define biological lineage order:
# angusticeps (maternal) first, then deppii (paternal) for consistency
seg_plot$chrom_lineage <- factor(
  seg_plot$chrom_lineage,
  levels = c(
    "angusticeps",
    "deppii"
  )
)

# determine chromosome order numerically within lineage
chrom_order <- unique(
  seg_plot[
    order(
      seg_plot$chrom_number,
      seg_plot$chrom_lineage
    ),
    "seg_chrom"
  ]
)

# convert chromosome name to an ordered factor
seg_plot$seg_chrom <- factor(
  seg_plot$seg_chrom,
  levels = chrom_order
)


# == NUMERICAL SUMMARY ==
# exact window-level means and medians
summary_list <- lapply(split(seg_plot, seg_plot$display_group), function(d) {
  data.frame(
      group = as.character(d$display_group[1]),
      n_windows = nrow(d),
      mean_5mC = mean(d$pct_5mC, na.rm = TRUE),
      median_5mC = median(d$pct_5mC, na.rm = TRUE),
      sd_5mC = sd(d$pct_5mC, na.rm = TRUE),
      mean_informative_calls = mean(d$total_calls, na.rm = TRUE),
      median_informative_calls = median(d$total_calls, na.rm = TRUE),
      stringsAsFactors = FALSE
  )
})

window_summary <- do.call(rbind, summary_list)
rownames(window_summary) <- NULL

cat("Window-level summary:\n")
print(window_summary)
cat("\n")


# == STRIP / JITTER PLOT ==
# each point = one retained 100-kb genomic window
# jitter spreads overlapping points horizontally (does not alter y-values)
p_strip <- ggplot(seg_plot,
      aes(
        x = display_group,
        y = pct_5mC,
        color = display_group
      )
    ) +
    # each point = one retained window
    geom_jitter(
      width = 0.15,
      height = 0,
      alpha = POINT_ALPHA,
      size = POINT_SIZE
    ) +
    # IQR boxplot
    # geom_boxplot(
    #   width = 0.12,
    #   fill = "white",
    #   color = "black",
    #   linewidth = 0.4,
    #   outlier.shape = NA
    # ) +
    # white diamond = median methylation across retained windows in that group
    stat_summary(
      fun = median,
      geom = "point",
      shape = 23,
      size = 3,
      fill = "white",
      color = "black"
    ) +
    scale_color_manual(values = GROUP_COLORS) +
    scale_y_continuous(
      limits = c(0, 100),
      breaks = seq(0, 100, by = 20),
      expand = expansion(mult = c(0, 0.02))
    ) +
    scale_x_discrete(
      labels = c(
        "A. angusticeps-derived" = expression(italic("A. angusticeps") * "-derived"),
        "A. deppii-derived" = expression(italic("A. deppii") * "-derived"),
        "Genome" = "Genome",
        "Unplaced" = "Unplaced"
      )
    ) +
    labs(
      x = NULL,
      y = "5mC (%)",
      title = PLOT_TITLE,
      subtitle = paste0(PLOT_SUBTITLE)
    ) +
    theme_classic(base_size = 12) +
    theme(
      legend.position = "none",
      plot.title = element_text(face = "bold"),
      axis.text.x = element_text(size = 11)
    )


# == VIOLIN + WINDOW POINTS ==
# violin width represents the density of windows at each methylation level
# points show the actual retained windows so the density is not shown alone
p_violin <- ggplot(seg_plot,
      aes(
        x = display_group,
        y = pct_5mC,
        fill = display_group
      )
    ) +
    geom_violin(
      trim = FALSE,
      alpha = VIOLIN_ALPHA,
      color = "black"
    ) +
    # IQR boxplot
    geom_boxplot(
      width = 0.12,
      fill = "white",
      color = "black",
      linewidth = 0.4,
      outlier.shape = NA
    ) +
    # geom_jitter(
    #     aes(color = display_group),
    #     width = 0.12,
    #     height = 0,
    #     alpha = 0.12,
    #     size = 0.5
    # ) +
    # stat_summary(
    #     fun = median,
    #     geom = "point",
    #     shape = 23,
    #     size = 3,
    #     fill = "white",
    #     color = "black"
    # ) +
    scale_fill_manual(values = GROUP_COLORS) +
    scale_color_manual(values = GROUP_COLORS) +
    scale_y_continuous(
      limits = c(0, 100),
      breaks = seq(0, 100, by = 20),
      expand = expansion(mult = c(0, 0.02))
    ) +
    scale_x_discrete(
    labels = c(
      "A. angusticeps-derived" = expression(italic("A. angusticeps") * "-derived"),
      "A. deppii-derived" = expression(italic("A. deppii") * "-derived"),
      "Genome" = "Genome",
      "Unplaced" = "Unplaced"
      )
    ) +
    labs(
      x = NULL,
      y = "5mC (%)",
      title = PLOT_TITLE,
      subtitle = paste0(PLOT_SUBTITLE)
    ) +
    theme_classic(base_size = 12) +
    theme(
      legend.position = "none",
      plot.title = element_text(face = "bold"),
      axis.text.x = element_text(size = 11)
    )


