# == ALL CHROMOSOMES AS FACETS ==
# exploratory/supplementary figure
# each panel has its own x-axis range because chromosome lengths differ
# y-axis remains fixed at 0-100% for direct methylation comparison
p_facets <- ggplot(seg_plot,
      aes(
          x = midpoint_Mb,
          y = pct_5mC,
          color = display_group
      )
    ) +
    geom_line(linewidth = 0.15, alpha = 0.7) +
    # geom_point(size = 0.3, alpha = 0.6) +
    facet_wrap(
      ~ seg_chrom,
      scales = "free_x"
    ) +
    scale_color_manual(values = GROUP_COLORS) +
    coord_cartesian(ylim = c(Y_MIN, Y_MAX)) +
    scale_x_discrete(
    labels = c(
      "A. angusticeps-derived" = expression(italic("A. angusticeps") * "-derived"),
      "A. deppii-derived" = expression(italic("A. deppii") * "-derived"),
      "Genome" = "Genome",
      "Unplaced" = "Unplaced"
      )
    ) +
    labs(
      x = "Position (Mb)",
      y = "5mC (%)",
      title = PLOT_TITLE,
      subtitle = "Window-level methylation by chromosome",
      color = "Group"
    ) +
    theme_classic(base_size = 9) +
    theme(
      plot.title = element_text(face = "bold"),
      strip.text = element_text(size = 7),
      legend.position = "bottom"
    )


# == SAVE OUTPUTS ==
# PDF for vector-based figures
# PNG at 300 dpi for presentation/quick sharing

if (!is.null(OUTPUT_DIR)) {

  dir.create(OUTPUT_DIR, recursive = TRUE, showWarnings = FALSE)

  # save numerical summary used for plots
  write.csv(
    window_summary,
    file.path(OUTPUT_DIR, "segmeth_window_summary.csv"),
    row.names = FALSE
  )

  # width = 4.5 for genomes; width = 6 for subgenomes
  ggsave(
    file.path(OUTPUT_DIR, "segmeth_strip_plot.pdf"),
    plot = p_strip,
    width = 4.5,
    height = 5
  )

  ggsave(
    file.path(OUTPUT_DIR, "segmeth_strip_plot.png"),
    plot = p_strip,
    width = 4.5,
    height = 5,
    dpi = 300
  )

  ggsave(
    file.path(OUTPUT_DIR, "segmeth_violin_plot.pdf"),
    plot = p_violin,
    width = 4.5,
    height = 5
  )

  ggsave(
    file.path(OUTPUT_DIR, "segmeth_violin_plot.png"),
    plot = p_violin,
    width = 4.5,
    height = 5,
    dpi = 300
  )

    # if (exists("p_chr")) {
    #     ggsave(
    #         file.path(OUTPUT_DIR,
    #             paste0("segmeth_", CHROM_TO_PLOT, "_landscape.pdf")
    #         ),
    #         plot = p_chr,
    #         width = 9,
    #         height = 4
    #     )
    # }

  ggsave(
    file.path(OUTPUT_DIR, "segmeth_all_chromosomes_facets.pdf"),
    plot = p_facets,
    width = 12,
    height = 10
  )
  
  ggsave(
    file.path(OUTPUT_DIR, "segmeth_all_chromosomes_facets.png"),
    plot = p_facets,
    width = 12,
    height = 10
  )

  cat("Plots and summary written to:\n  ", OUTPUT_DIR, "\n", sep = "")
}
